117	  private static final class JavaNioCreator extends TempFileCreator {
118	    @Override
119	    File createTempDir() {
120	      try {
121	        return java.nio.file.Files.createTempDirectory(
122	                Paths.get(JAVA_IO_TMPDIR.value()), /* prefix= */ null, directoryPermissions.get())
123	            .toFile();
