144	    private static final PermissionSupplier filePermissions;
145	    private static final PermissionSupplier directoryPermissions;
146	
147	    static {
148	      Set<String> views = FileSystems.getDefault().supportedFileAttributeViews();
149	      if (views.contains("posix")) {
150	        filePermissions = () -> asFileAttribute(PosixFilePermissions.fromString("rw-------"));
151	        directoryPermissions = () -> asFileAttribute(PosixFilePermissions.fromString("rwx------"));
152	      } else if (views.contains("acl")) {
153	        filePermissions = directoryPermissions = userPermissions();
154	      } else {
155	        filePermissions =
156	            directoryPermissions =
157	                () -> {
158	                  throw new IOException("unrecognized FileSystem type " + FileSystems.getDefault());
159	                };
160	      }
161	    }
162	
163	    private static PermissionSupplier userPermissions() {
164	      try {
165	        FileAttribute<ImmutableList<AclEntry>> attribute =
166	            userAclAttribute(lookupCurrentUser());
167	        return () -> attribute;
168	      } catch (IOException e) {
169	        // We throw a new exception each time so that the stack trace is right.
170	        return () -> {
171	          throw new IOException("Could not find user", e);
172	        };
173	      }
174	    }
175	
176	    private static UserPrincipal lookupCurrentUser() throws IOException {
177	      return FileSystems.getDefault()
178	          .getUserPrincipalLookupService()
179	          .lookupPrincipalByName(getUsername());
180	    }
