182	    private static FileAttribute<ImmutableList<AclEntry>> userAclAttribute(UserPrincipal user) {
183	      ImmutableList<AclEntry> acl =
184	          ImmutableList.of(
185	              AclEntry.newBuilder()
186	                  .setType(ALLOW)
187	                  .setPrincipal(user)
188	                  .setPermissions(EnumSet.allOf(AclEntryPermission.class))
189	                  .setFlags(DIRECTORY_INHERIT, FILE_INHERIT)
190	                  .build());
191	      return new FileAttribute<ImmutableList<AclEntry>>() {
192	        @Override
193	        public String name() {
194	          return "acl:acl";
195	        }
196	
197	        @Override
198	        public ImmutableList<AclEntry> value() {
199	          return acl;
200	        }
201	      };
202	    }
