204	    private static String getUsername() {
205	      /*
206	       * https://github.com/google/guava/issues/6634: ProcessHandle has more accurate information,
207	       * but that class isn't available under all environments that we support. We use it if
208	       * available and fall back if not.
209	       */
210	      String fromSystemProperty = requireNonNull(USER_NAME.value());
211	
212	      try {
213	        Class<?> processHandleClass = Class.forName("java.lang.ProcessHandle");
214	        Class<?> processHandleInfoClass = Class.forName("java.lang.ProcessHandle$Info");
215	        Class<?> optionalClass = Class.forName("java.util.Optional");
216	        /*
217	         * We don't *need* to use reflection to access Optional: It's available on all JDKs we
218	         * support, and Android code won't get this far, anyway, because ProcessHandle is
219	         * unavailable. But given how much other reflection we're using, we might as well use it
220	         * here, too, so that we don't need to also suppress an AndroidApiChecker error.
221	         */
222	
223	        Method currentMethod = processHandleClass.getMethod("current");
224	        Method infoMethod = processHandleClass.getMethod("info");
225	        Method userMethod = processHandleInfoClass.getMethod("user");
226	        Method orElseMethod = optionalClass.getMethod("orElse", Object.class);
227	
228	        Object current = currentMethod.invoke(null);
229	        Object info = infoMethod.invoke(current);
230	        Object user = userMethod.invoke(info);
231	        return (String) requireNonNull(orElseMethod.invoke(user, fromSystemProperty));
232	      } catch (ClassNotFoundException runningUnderAndroidOrJava8) {
233	        /*
234	         * I'm not sure that we could actually get here for *Android*: I would expect us to enter
235	         * the POSIX code path instead. And if we tried this code path, we'd have trouble unless we
236	         * were running under a new enough version of Android to support NIO.
237	         *
238	         * So this is probably just the "Windows Java 8" case. In that case, if we wanted *another*
239	         * layer of fallback before consulting the system property, we could try
240	         * com.sun.security.auth.module.NTSystem.

120	        out.write(b[i]);
121	      }
122	    } else {
123	      out.write(b, off, len);
124	    }
125	    out.flush(); // for coverage
126	  }
