202	    FileBackedOutputStream out = new FileBackedOutputStream(/* fileThreshold= */ 10);
203	    ByteSource source = out.asByteSource();
204	
205	    byte[] chunk1 = newPreFilledByteArray(8); // Below threshold
206	    byte[] chunk2 = newPreFilledByteArray(5); // Crosses threshold
207	    byte[] chunk3 = newPreFilledByteArray(20); // More data to file
208	
209	    out.write(chunk1);
210	    assertThat(out.getFile()).isNull();
211	
212	    out.write(chunk2);
213	    assertThat(out.getFile()).isNotNull();
214	    assertThat(source.read()).isEqualTo(concat(chunk1, chunk2));
215	
216	    out.write(chunk3);
217	    assertThat(source.read()).isEqualTo(concat(chunk1, chunk2, chunk3));
218	
219	    out.reset();
220	  }
