234	  /**
235	   * Per-instance state, extracted to a separate object so that {@link FinalizableReference} can
236	   * still access it after the {@link FileBackedOutputStream} and {@link ByteSource} have been
237	   * garbage collected.
238	   */
239	  private static final class State {
240	    final int fileThreshold;
241	    final boolean resetWhenGarbageCollected;
242	
243	    @GuardedBy("this")
244	    @Nullable MemoryOutput memory;
245	
246	    @GuardedBy("this")
247	    @Nullable File file;
248	
249	    @GuardedBy("this")
250	    OutputStream out;
251	
252	    State(int fileThreshold, boolean resetWhenGarbageCollected) {
253	      this.fileThreshold = fileThreshold;
254	      this.resetWhenGarbageCollected = resetWhenGarbageCollected;
255	      this.memory = new MemoryOutput();
256	      this.out = requireNonNull(memory);
257	    }
258	
259	    synchronized @Nullable File getFile() {
260	      return file;
261	    }
262	
263	    synchronized InputStream openInputStream() throws IOException {
264	      if (file != null) {
265	        return new FileInputStream(file);
266	      } else {
267	        // requireNonNull is safe because we always have either `file` or `memory`.
268	        requireNonNull(memory);
269	        return new ByteArrayInputStream(memory.getBuffer(), 0, memory.getCount());
270	      }
271	    }
272	
273	    synchronized void reset() throws IOException {
274	      try {
275	        close();
276	      } finally {
277	        resetMemoryBuffer();
278	        deleteFileIfPresent();
279	      }
280	    }
281	
282	    synchronized void write(int b) throws IOException {
283	      update(1);
284	      out.write(b);
285	    }
286	
287	    synchronized void write(byte[] b, int off, int len) throws IOException {
288	      update(len);
289	      out.write(b, off, len);
290	    }
291	
292	    synchronized void close() throws IOException {
293	      out.close();
294	    }
295	
296	    synchronized void flush() throws IOException {
297	      out.flush();
298	    }
299	
300	    /**
301	     * Checks if writing {@code len} bytes would go over threshold, and switches to file buffering
302	     * if so.
303	     */
304	    @GuardedBy("this")
305	    void update(int len) throws IOException {
306	      if (memory != null && memory.getCount() > fileThreshold - len) {
307	        promoteToFile();
308	      }
309	    }
310	
311	    @GuardedBy("this")
312	    private void resetMemoryBuffer() {
313	      if (memory == null) {
314	        memory = new MemoryOutput();
315	      } else {
316	        memory.reset();
317	      }
318	      out = requireNonNull(memory);
319	    }
320	
321	    @GuardedBy("this")
322	    private void deleteFileIfPresent() throws IOException {
323	      if (file == null) {
324	        return;
325	      }
326	      File deleteMe = file;
327	      file = null;
328	      if (!deleteMe.delete()) {
329	        throw new IOException("Could not delete: " + deleteMe);
330	      }
331	    }
332	
333	    @GuardedBy("this")
334	    private void promoteToFile() throws IOException {
335	      File temp = TempFileCreator.INSTANCE.createTempFile("FileBackedOutputStream");
336	      if (resetWhenGarbageCollected) {
337	        // References are not guaranteed to be collected on system shutdown; this is insurance.
338	        temp.deleteOnExit();
339	      }
340	      FileOutputStream transfer = null;
341	      try {
342	        transfer = new FileOutputStream(temp);
343	        MemoryOutput memory = requireNonNull(this.memory);
344	        transfer.write(memory.getBuffer(), 0, memory.getCount());
345	        transfer.flush();
346	        out = transfer;
347	        file = temp;
348	        this.memory = null;
349	      } catch (IOException e) {
350	        if (transfer != null) {
351	          try {
352	            transfer.close();
353	          } catch (IOException closeException) {
354	            e.addSuppressed(closeException);
355	          }
356	        }
357	        temp.delete();
358	        throw e;
359	      }
360	    }
361	  }
