363	  /** Ensures that {@code o} is not garbage collected until this point in the code. */
364	  @VisibleForTesting
365	  // We call the method only after checking that it's present.
366	  @IgnoreJRERequirement
367	  @SuppressWarnings({
368	    "Java8ApiChecker",
369	    "NewApi",
370	    // This method is a helper, which we call from a `finally` block, as recommended.
371	    "ReachabilityFenceUsage",
372	  })
373	  static void reachabilityFence(@Nullable Object o) {
374	    if (IS_REACHABILITY_FENCE_METHOD_USABLE) {
375	      Reference.reachabilityFence(o);
376	    }
377	  }
